function normalizeCloudRepo(e){const t=e.trim();if(!t)return;const n=parseGitUrl(`git:${t}`);if(!n)return;const r=n.path.split(`/`).filter(Boolean);if(!n.host||r.length<2)return;return`${n.host}/${r.join(`/`)}`.toLowerCase()}export{parseGitUrl as n,normalizeCloudRepo as t};